import 'package:flutter/material.dart';import '../services/app_services.dart';
class ChatPage extends StatefulWidget{final String conversationId,roomId,receiverId;const ChatPage({super.key,required this.conversationId,required this.roomId,required this.receiverId});State<ChatPage> createState()=>_Chat();}
class _Chat extends State<ChatPage>{final ctl=TextEditingController();final chat=ChatService();Future<void> send(){final t=ctl.text.trim();if(t.isEmpty)return Future.value();ctl.clear();return chat.send(conversationId:widget.conversationId,receiverId:widget.receiverId,text:t,roomId:widget.roomId);}
Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Chat')),body:Column(children:[Expanded(child:StreamBuilder(stream:chat.messages(widget.conversationId),builder:(c,s){final docs=s.data?.docs??[];return ListView.builder(reverse:true,padding:const EdgeInsets.all(12),itemCount:docs.length,itemBuilder:(c,i){final m=docs[i].data();final mine=m['senderId']==auth.currentUser!.uid;return Align(alignment:mine?Alignment.centerRight:Alignment.centerLeft,child:Container(margin:const EdgeInsets.only(bottom:8),padding:const EdgeInsets.symmetric(horizontal:14,vertical:10),decoration:BoxDecoration(color:mine?Theme.of(c).colorScheme.primaryContainer:Colors.white,borderRadius:BorderRadius.circular(18)),child:Text(m['text']??'')));}));})),SafeArea(child:Padding(padding:const EdgeInsets.fromLTRB(12,6,12,10),child:Row(children:[Expanded(child:TextField(controller:ctl,textInputAction:TextInputAction.send,onSubmitted:(_)=>send(),decoration:const InputDecoration(hintText:'Write a message',filled:true))),IconButton(onPressed:send,icon:const Icon(Icons.send))])))]));}
}
